import{_ as o,o as e,c as r,ag as a}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学快报 | 2026年7月20日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-20.md","filePath":"science-log/src/reconstructed/2026-07-20.md"}'),n={name:"science-log/src/reconstructed/2026-07-20.md"};function s(i,t,u,l,p,q){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="🔬-科学快报-2026年7月20日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月20日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月20日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月20日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日（周一）Nature 命中 7 条<strong>全为 d41586 新闻/Briefing</strong>、Science 命中 5 条<strong>全为 news/Adviser</strong>，两家均无研究论文刊出；故科学 5 篇全部取自 PNAS 当日（2026-07-20）实际刊出的研究论文。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607200000 TO 202607202359]</code>（cs.AI，命中 40 篇）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧲-厌氧纤毛虫靠-三方共生-获得趋磁能力" tabindex="-1">🧲 厌氧纤毛虫靠&quot;三方共生&quot;获得趋磁能力 <a class="header-anchor" href="#🧲-厌氧纤毛虫靠-三方共生-获得趋磁能力" aria-label="Permalink to &quot;🧲 厌氧纤毛虫靠&quot;三方共生&quot;获得趋磁能力&quot;">​</a></h3><p><strong>Magnetotaxis in an anaerobic ciliate via tripartite syntrophy</strong><em>PNAS（2026-07-20）</em></p><p>趋磁行为此前被认为是细菌的专利，通过遗传控制的磁小体生物矿化实现。作者报告了一个新种纤毛虫 <em>Tropidoatractus magnetotacticus</em> sp. nov.：其体内含有大量杆状细菌，细菌内排列成椭球状&quot;项链式&quot;平行链的亚铁磁性磁铁矿（Fe₃O₄）纳米颗粒赋予宿主净磁矩，使纤毛虫沿地磁场游动。基因组分析在磁分选后的宿主细胞中检出 Thermodesulfobacteriota 类群的趋磁细菌种群，其编码并表达磁小体基因簇，与已知外共生体 <em>Candidatus</em> Desulfarcum epimagneticum 高度相近。这是真核生物通过<strong>共生而非自身基因</strong>获得趋磁性的直接案例，为真核趋磁的演化路径提供了&quot;水平获取&quot;解释。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2609513123" target="_blank" rel="noreferrer">10.1073/pnas.2609513123</a></p><h3 id="⚛️-光合放氧复合物能用脂肪族侧链-翻译后造出-羧基配体" tabindex="-1">⚛️ 光合放氧复合物能用脂肪族侧链&quot;翻译后造出&quot;羧基配体 <a class="header-anchor" href="#⚛️-光合放氧复合物能用脂肪族侧链-翻译后造出-羧基配体" aria-label="Permalink to &quot;⚛️ 光合放氧复合物能用脂肪族侧链&quot;翻译后造出&quot;羧基配体&quot;">​</a></h3><p><strong>Posttranslational generation of carboxylate ligands from aliphatic side chains in the photosynthetic oxygen-evolving complex</strong><em>PNAS（2026-07-20）</em></p><p>光系统 II 的放氧复合物（OEC）以 Mn₄CaO₅ 簇催化水裂解放氧，其锰配位依赖 Asp/Glu 羧基。作者先前的实验显示，把锰簇的 Asp/Glu 配体突变为 His 或 Asn/Gln 后，这些残基会在翻译后被&quot;改回&quot;羧基。本文进一步把 D1-Asp170 突变为 Val/Leu/Ile、D1-Glu189 突变为 Leu/Ile——这些脂肪族侧链<strong>根本没有可反应的官能团</strong>——结果仍在翻译后生成了 Asp/Glu 或其衍生物，并部分恢复了放氧活性。这意味着存在一类全新的翻译后修饰，且非标准 Asp/Glu 衍生物也能充当锰簇的羧基配体。对理解 OEC 在大氧化事件（约 24 亿年前）之前如何在祖先 PSII 中&quot;长出来&quot;提供了化学上的可行性。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2610028123" target="_blank" rel="noreferrer">10.1073/pnas.2610028123</a></p><h3 id="🧊-2025-与-2026-年创纪录低冰情-恢复-了北极冬季海冰下降趋势" tabindex="-1">🧊 2025 与 2026 年创纪录低冰情&quot;恢复&quot;了北极冬季海冰下降趋势 <a class="header-anchor" href="#🧊-2025-与-2026-年创纪录低冰情-恢复-了北极冬季海冰下降趋势" aria-label="Permalink to &quot;🧊 2025 与 2026 年创纪录低冰情&quot;恢复&quot;了北极冬季海冰下降趋势&quot;">​</a></h3><p><strong>Record-low 2025 and 2026 ice extents restore Arctic winter sea-ice decline</strong><em>PNAS（2026-07-20）</em></p><p>近期分析曾认为 2020 年代初北极冬季海冰范围的十年尺度下降速率在减弱，20 年趋势已统计不显著。作者用更新的观测指出：2025 与 2026 年冬季的极端低冰情扭转了这一图景——冰增长期与峰值期的海冰范围双双回到历史最低，20 年下降趋势重新变得显著。进一步用 CMIP6 模式类比显示，2025 年的下跌虽不寻常，但在同等北极增暖条件下物理上合理，更符合&quot;冬季海冰持续减少&quot;而非&quot;回到 2020 年代初水平&quot;。这提醒：短期趋势平台的判读极易被十年内自然变率误导，样本窗口的选择本身就能翻转结论。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614134123" target="_blank" rel="noreferrer">10.1073/pnas.2614134123</a></p><h3 id="🫧-上皮-穹顶-在水压下自行振荡-生长、塌陷与黏附断裂的博弈" tabindex="-1">🫧 上皮&quot;穹顶&quot;在水压下自行振荡：生长、塌陷与黏附断裂的博弈 <a class="header-anchor" href="#🫧-上皮-穹顶-在水压下自行振荡-生长、塌陷与黏附断裂的博弈" aria-label="Permalink to &quot;🫧 上皮&quot;穹顶&quot;在水压下自行振荡：生长、塌陷与黏附断裂的博弈&quot;">​</a></h3><p><strong>Shape instabilities of active epithelial domes under hydraulic stress: Growth, collapse, and oscillation</strong><em>PNAS（2026-07-20）</em></p><p>液体充盈的上皮腔体（发育中的管腔、胚胎腔、单层脱离形成的穹顶）如何在静水压与黏附断裂之间协调形变，长期不清楚。中国科学技术大学近代力学系团队以 MDCK 上皮穹顶为模型，结合活细胞成像与极小理论模型，把主动离子转运、应变刚化组织力学、细胞—细胞黏附的断裂—愈合动力学耦合起来。模型给出五个动力学相：塌陷、稳定生长、生长—塌陷、振荡、无界生长，其分界由离子泵驱动的水压与细胞—基底/细胞—细胞黏附断裂之间的竞争决定。关键结论是：渗透内流与断裂泄漏之间的水力反馈会产生自持振荡，与断裂力学中的黏滑（stick-slip）不稳定性同构；药物实验进一步支持了该机制。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2529071123" target="_blank" rel="noreferrer">10.1073/pnas.2529071123</a></p><h3 id="🐒-猴子的几何直觉与人类是-连续-的-而非-断裂-的" tabindex="-1">🐒 猴子的几何直觉与人类是&quot;连续&quot;的，而非&quot;断裂&quot;的 <a class="header-anchor" href="#🐒-猴子的几何直觉与人类是-连续-的-而非-断裂-的" aria-label="Permalink to &quot;🐒 猴子的几何直觉与人类是&quot;连续&quot;的，而非&quot;断裂&quot;的&quot;">​</a></h3><p><strong>Continuity in geometric intuition between humans and monkeys</strong><em>PNAS（2026-07-20）</em></p><p>几何直觉长期被视为人类智能的标志，流行解释是：人类用离散的符号特征编码形状，其他灵长类只用连续知觉特征。本文用匹配样本任务检验猴子是否共享人类的几何表征。结果显示猴子与人类一样，会把高层知觉表征与抽象符号表征结合起来——支持跨物种&quot;渐进的、定量的连续&quot;，而非&quot;范畴的、定性的鸿沟&quot;。更反直觉的是：猴子在处理<strong>旋转</strong>几何图形时对符号特征的依赖，比学前儿童处理<strong>未旋转</strong>图形时更强，提示看似&quot;符号化&quot;的表征在很大程度上可由旋转不变性知觉自然涌现。这对&quot;语言/符号是几何唯一来源&quot;的强主张构成直接压力。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2532934123" target="_blank" rel="noreferrer">10.1073/pnas.2532934123</a></p><h3 id="🧠-智能可以从-可学习的新奇性-里长出来" tabindex="-1">🧠 智能可以从&quot;可学习的新奇性&quot;里长出来 <a class="header-anchor" href="#🧠-智能可以从-可学习的新奇性-里长出来" aria-label="Permalink to &quot;🧠 智能可以从&quot;可学习的新奇性&quot;里长出来&quot;">​</a></h3><p><strong>Intelligence from Learnable Novelty</strong><em>arXiv（2026-07-20）</em> · Yanbo Zhang, Michael Levin</p><p>智能在不同学科里有不同名字：统计学与机器学习叫&quot;数据压缩&quot;，动力系统叫&quot;通用计算&quot;，智能体叫&quot;适应行为&quot;。作者指出两种最主流的内驱目标存在镜像式失败：新奇搜索（追求惊奇）会被噪声电视雪花迷住，自由能原理（回避惊奇）最舒服的地方是黑屋子。两者失败同因——把&quot;学习者能转化为知识的惊奇&quot;和&quot;永远无法转化的惊奇&quot;当成同一个量。本文把其中可学习的部分定义为 <strong>learnable novelty</strong>，并给出基于廉价可微储层计算机（reservoir computer）的闭式估计器。这一提法把压缩、计算、适应三个&quot;智能投影&quot;统一到同一信息量之下。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.18433" target="_blank" rel="noreferrer">2607.18433</a></p><h3 id="🎭-决定-llm-智能体行为的不是人设-是-故事的框架" tabindex="-1">🎭 决定 LLM 智能体行为的不是人设，是&quot;故事的框架&quot; <a class="header-anchor" href="#🎭-决定-llm-智能体行为的不是人设-是-故事的框架" aria-label="Permalink to &quot;🎭 决定 LLM 智能体行为的不是人设，是&quot;故事的框架&quot;&quot;">​</a></h3><p><strong>The Story Shapes the Agent: Narrative Priors in LLM Behavior</strong><em>arXiv（2026-07-20）</em> · Yixuan Wang, James Lester, Shashank Srivastava</p><p>人设提示（persona prompting）被广泛用于操控 LLM 智能体，但任务的<strong>叙事框架</strong>可能比指定人设更重要。作者用结构同构法做了严格隔离：三个文本调查游戏共享完全相同的动作空间、阶段推进与资源约束，只改变叙事（疾病调查 / IT 排障 / 谋杀悬疑）。在 3 个模型 × 10 个人设、共 1,890 局会话中，他们识别出&quot;叙事先验&quot;——由故事框架激活、与决策结构无关的系统性动作倾向。叙事先验解释的行为方差比人设多 5–31 倍，跨模型架构一致，且在三个领域中的两个与任务成功率<strong>负相关</strong>。真正能跨叙事迁移的人设效应来自&quot;行为锚点&quot;式描述。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.18566" target="_blank" rel="noreferrer">2607.18566</a></p><h3 id="📉-一句-只回-json-就让-44-个模型的答案多样性塌缩" tabindex="-1">📉 一句&quot;只回 JSON&quot;，就让 44 个模型的答案多样性塌缩 <a class="header-anchor" href="#📉-一句-只回-json-就让-44-个模型的答案多样性塌缩" aria-label="Permalink to &quot;📉 一句&quot;只回 JSON&quot;，就让 44 个模型的答案多样性塌缩&quot;">​</a></h3><p><strong>Structured Output Collapses Answer Diversity Across 44 Language Models</strong><em>arXiv（2026-07-20）</em> · Tapan Parikh</p><p>当模型需要从大量同样合法的选项里挑一个答案时，仅一句格式要求——&quot;Reply with JSON only&quot;——就会改变它挑哪个。作者复跑了 One-Word Census：31 个宽答案空间类别提示 × 44 个模型，这次只<strong>请求</strong> JSON 输出（无 schema 强制、无约束解码）。收敛显著加深：在无约束的&quot;随便挑一个词&quot;提示上，众数答案占比从 41% 升到 64%，不同答案数从 52 降到 36，平均答案选择 surprisal 从 1.80 bit 降到 1.58 bit。这个&quot;税&quot;是累进的：44 个模型中有 6 个个体显著移动（BH-FDR q=.10），全部朝众数靠，且以最有特色的模型为首，而&quot;从众地板&quot;纹丝不动。它是<strong>锐化器</strong>而非重排器——31 个类别里有 28 个的普通对话众数答案存活。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.18476" target="_blank" rel="noreferrer">2607.18476</a></p><h3 id="🗺️-规划可以是纯无模型-rl-的涌现行为-决定因素是隐藏态结构" tabindex="-1">🗺️ 规划可以是纯无模型 RL 的涌现行为，决定因素是隐藏态结构 <a class="header-anchor" href="#🗺️-规划可以是纯无模型-rl-的涌现行为-决定因素是隐藏态结构" aria-label="Permalink to &quot;🗺️ 规划可以是纯无模型 RL 的涌现行为，决定因素是隐藏态结构&quot;">​</a></h3><p><strong>Planning as Emergent Behavior in Reinforcement Learning with Relational Hidden States</strong><em>arXiv（2026-07-20）</em> · Armin Sommer</p><p>RL 传统上分模型基与无模型：前者在世界模型上做前瞻规划，后者学反应式状态—动作映射。近期工作已显示规划可以从<strong>纯无模型</strong> RL 中涌现，但涌现条件一直不清楚。本文给出证据：决定因素是神经架构的<strong>隐藏态结构</strong>。一个由&quot;关系型隐藏态&quot;组成的网络——每个隐藏态锚定到一个环境状态、并沿学到的关系交换消息——自发获得了规划机制：其隐藏态在学到的关系里恢复了环境的转移结构，并改进了策略。这把&quot;是否规划&quot;从算法标签问题改写为架构表征问题：转移结构一旦被结构化地嵌入表征，前瞻就是它的副产品。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.18589" target="_blank" rel="noreferrer">2607.18589</a></p><h3 id="⏳-chronos-漏洞-把攻击与灾难解耦的-记忆投毒" tabindex="-1">⏳ Chronos 漏洞：把攻击与灾难解耦的&quot;记忆投毒&quot; <a class="header-anchor" href="#⏳-chronos-漏洞-把攻击与灾难解耦的-记忆投毒" aria-label="Permalink to &quot;⏳ Chronos 漏洞：把攻击与灾难解耦的&quot;记忆投毒&quot;&quot;">​</a></h3><p><strong>The Chronos Vulnerability: A Taxonomy of Temporal Persistence and Memory-Based Deception in Agentic AI</strong><em>arXiv（2026-07-20）</em> · Om Narayan, Ramkinker Singh, Praveen Baskar</p><p>从无状态生成模型到有状态自主智能体的架构演化，带来了长期规划与企业工作流自动化能力，也引入了新型安全威胁。作者把它命名为 <strong>Chronos 漏洞</strong>：以记忆为载体的攻击（记忆注入 MINJA、潜伏者 sleeper agent）先污染智能体的内部信念系统，再把攻击向量与最终灾难事件在时间上<strong>解耦</strong>——注入发生在过去，破坏发生在未来，中间隔着多次正常交互。本文在 World of Workflows 基准上形式化了持久化攻击的威胁模型与&quot;动力学盲区&quot;（Dynamics Blindness）问题，并证明传统端点内容过滤对有状态架构根本不充分。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.19433" target="_blank" rel="noreferrer">2607.19433</a></p><blockquote><p>📅 日期：2026-07-20 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 ｜ 期号：当日无发布（前一发布期为第21期 2026-07-11，后一期为第22期 2026-09-11），故记作（第 ? 期 · 事后重建版）</p></blockquote>',44)])])}const c=o(n,[["render",s]]);export{g as __pageData,c as default};
